    ['Before launching','Open System & maintenance → Launch checks. Review HTTPS, settings, installation state and any warnings before publishing.','admin/launch/']]],
   'pages'=>['Pages & imagery','Edit website introductions, backgrounds and photographs',[
    ['Edit a page','Open Website content → Pages & homepage. Choose the page, update Subtitle, Page text or Feature image, then Save private draft. Preview the draft and choose Publish approved content to make it live. Leaving optional Page text empty keeps the designed introduction on Home, Band and Press. Changes to the member roster update only unedited default copy; your explicitly published story is preserved.','admin/content/?kind=page'],
    ['Edit headings inside pages','Open Pages & homepage and select the relevant designed page. Fields labeled for that page, such as Home · Music section heading or Band · Member profiles heading, control individual section titles. Leave them blank to keep the approved original typography; save, preview and publish to go live.','admin/content/?kind=page'],
    ['Change a page headline','Open Pages & homepage, edit the Page headline or Small heading above headline, and publish. Leaving these optional fields empty keeps the approved default text.','admin/content/?kind=page'],
    ['Edit the Band page button','Open the Band page record in Pages & homepage. Set Primary button label and an optional HTTPS destination; leaving the destination blank retains the internal Press link. Preview before publishing.','admin/content/?kind=page'],
    ['Edit the Booking page','Open Pages & homepage and select Booking. Edit its small heading, headline, introduction, artwork and primary button label or HTTPS destination. An optional Booking details heading appears above the inquiry form when supplied. Save and preview a private draft; the inquiry form is disabled in preview. Publish approved content to change the live Booking presentation without changing inquiry handling.','admin/content/?kind=page'],
    ['Replace an image','Open Media library to upload an approved photograph or artwork. Return to the page editor, select its Feature image, preview, then publish. Uploaded files do not automatically replace a public image.','admin/media/']]],
   'members'=>['Band members','Portraits, biographies and lineup order',[
    ['Import the established lineup','On a site with no saved member records, open Band members and expand Bring the existing lineup into the editor. Confirm import to create editable published names and instrument roles from the former public layout; then add approved portraits and biographies. Previously deleted members are never automatically restored.','admin/content/?kind=member'],
    ['Add a band member','Open Website content → Band members and select Add band member. Enter the name, musical role, biography and an approved image from Media library. Save, preview and publish.','admin/content/?kind=member'],
    ['Edit a biography or photograph','Select an existing member in Band members. Update Approved biography, Musical role or Approved portrait. Optionally describe the portrait for screen readers (overriding the Media library description for this profile), and add a verified HTTPS Member website. Save privately, preview, then publish. The public Band page shows the portrait on the left and the biography on the right on desktop.','admin/content/?kind=member'],
    ['Change lineup order','Open a member and change Sort order. Lower numbers appear first. Publish each edited member to update public ordering.','admin/content/?kind=member'],
    ['Remove a member','Open an existing member and use Remove band member with confirmation. Removal hides the profile; uploaded photographs are retained for safety.','admin/content/?kind=member']]],
   'music'=>['Music & performances','Albums, tracks, shows and venue ticket links',[
    ['Publish a release and tracks','Create an approved Music release with cover artwork. Then add Audio tracks and assign them to the release. Publish records when complete.','admin/content/?kind=release'],
    ['Publish an event','Add a show under Music & shows, enter the event date, timezone, location and admission status. For ticketed events use the venue’s HTTPS seller link, then publish.','admin/content/?kind=event']]],
   'media'=>['Media & press','Photo gallery, videos and press downloads',[
    ['Upload media','Use the Media library for approved images, audio and PDFs. Select uploaded files in the relevant content editor.','admin/media/'],
    ['Manage photos and video','Use Photo gallery for published photos and captions, Videos for approved YouTube/Vimeo links and posters, and Press downloads for PDF material.','admin/content/?kind=gallery']]],
   'audience'=>['Bookings & audience','Inquiries, newsletter and delivery monitoring',[
    ['Review booking inquiries','Open Booking inquiries to review submitted requests. A request is not a confirmed booking.','admin/bookings/'],
    ['Manage email delivery','Configure Email settings, test SMTP as available, then review the Delivery queue and Subscribers.','admin/communication/']]],
   'commerce'=>['Store & orders','Optional merchandise, checkout and fulfillment',[
    ['Prepare a store','Use Products & inventory, categories, shipping/tax policies and payment settings. Do not activate checkout until the merchant and policy checks are complete.','admin/shop/']]],
   'maintenance'=>['Settings & maintenance','Staff, backups, recovery and updates',[
    ['Manage access','Open Staff access to review permissions. Give each staff member only the access required for their work.','admin/staff/'],
    ['Backup before upgrading','Create and verify a backup before using Browser upgrades. Follow the version-specific upgrade notes; do not rerun the fresh installer on an existing site.','admin/backups/'],
    ['Check site settings','Use Website settings to maintain brand and site details. Use Installation health or Database updates only when needed.','admin/settings.php']]],
   'analytics'=>['Analytics & reporting','Understand audience reports without confusing visitors and visits',[
    ['Review audience trends','Open Analytics → Audience dashboard, choose a date range, and review traffic trends. Traffic counts depend on enabled collection and observed data.','admin/analytics/'],
    ['Explore visitor records','Use Visitor explorer to review the measured visits. Respect privacy and do not treat bot traffic as confirmed people.','admin/analytics/visitors.php'],
    ['Review geographic data','Open Geography data to inspect collected location summaries. Geo results are approximate, not exact visitor addresses.','admin/analytics/geography.php']]],
   'account'=>['Accounts & permissions','Maintain sign-in security and manage collaborators',[
    ['Update your account','Open Account & security to review your own account and sign-in options.','admin/account.php'],
    ['Manage staff permissions','Use Staff access to manage roles. Review access after role changes and keep owner privileges limited.','admin/staff/']]],
   'troubleshooting'=>['Troubleshooting','Resolve common publishing and operation problems',[
    ['Changes are not showing','Confirm you selected Publish approved content rather than Save private draft; reload the public page. Only published records appear in the public site.','admin/content/?kind=page'],
    ['Portrait or artwork is missing','Open Media library and verify the approved file exists. Then confirm the content record selects that image and was published. Do not delete shared images to fix a preview.','admin/media/'],
    ['Cannot publish a show','Check the required event fields including venue, date, timezone and city. Add the venue ticket link only when confirmed.','admin/content/?kind=event'],
    ['Email is not being delivered','Review SMTP configuration in Email settings and the Delivery queue. Check host certificate, encryption and credentials rather than switching to insecure delivery.','admin/communication/'],
    ['Site needs an update','Review Installation health, Database updates and Browser upgrades before taking action. Back up first and never run the fresh installer on an existing live site.','admin/installation.php'],
    ['Store unavailable','Commerce is optional and may be intentionally disabled. Review store activation and payment readiness without collecting transactions until provider acceptance is complete.','admin/shop/settings.php']]],
  ];
  foreach([['Find the right instructions','Open Help & guidance → Help Center, search by a task or select a topic. The Help for this screen shortcut is in the administration header, below the current screen title on narrow phones. Guides link directly to related admin screens; staff only see topics their permissions allow.','admin/help/']] as $guide){$topics['getting-started'][2][]=$guide;}
  foreach([['Publish a video','Go to Website content → Videos, add the approved YouTube or Vimeo URL, choose an optional poster image, save privately, preview and publish.','admin/content/?kind=video'],
           ['Manage press downloads','Open Press downloads and create an entry with a previously uploaded, approved PDF. Preview it, then publish it for visitors to access.','admin/content/?kind=press']] as $guide){$topics['media'][2][]=$guide;}
  foreach([['Add an audio track','Upload the authorized recording to Media library. Open Audio tracks, associate it with the correct release, add its title and duration, then save and publish.','admin/content/?kind=track']] as $guide){$topics['music'][2][]=$guide;}
  foreach([['Review newsletter subscribers','Open Subscribers and review subscription state and consent before sending. Never add addresses without permission.','admin/subscribers/'],
           ['Investigate delivery errors','Open Delivery queue to review pending or failed messages. Correct verified SMTP settings, then use the available retry actions only after checking duplicates.','admin/mail/']] as $guide){$topics['audience'][2][]=$guide;}
  foreach([['Organize products into categories','Open Product categories to create or maintain the organization of approved merchandise. Confirm that product category assignments display correctly.','admin/shop/categories.php'],
           ['Review customer accounts','Open Customers to review existing customer records according to your staff permissions. Avoid exporting private details unless business operations require them.','admin/shop/customers.php'],
           ['Manage fulfillment','Open Orders & fulfillment, review order status and verified payment before dispatching goods. Keep fulfillment records accurate.','admin/orders/'],
           ['Configure shipping and tax policies','Open Shipping, tax & terms; review required business policies and validate the results before activating checkout.','admin/orders/policy.php'],
           ['Set up payment processing','Open Payment settings and follow the gateway configuration and acceptance process. Keep credentials private; do not process live transactions before testing.','admin/orders/payments.php'],
           ['Inspect payment notifications','Review Payment notifications to understand webhook delivery and processing state. Never manually mark a payment received without provider confirmation.','admin/orders/webhooks.php'],
           ['Review store settings','Open Store settings to review optional commerce activation. Checkout stays disabled until merchant, inventory and policy acceptance is complete.','admin/shop/settings.php']] as $guide){$topics['commerce'][2][]=$guide;}
  foreach([['Control search and sharing','Open Search & sharing to review public discovery metadata and social previews. Make sure descriptions and artwork are approved before publication.','admin/discovery.php']] as $guide){$topics['account'][2][]=$guide;}
  foreach([['Apply browser upgrades safely','Take and verify a full backup first. Use Browser upgrades only for an unchanged, compatible layout. If an rc.8-or-earlier site is moving to grouped folders, follow docs/LAYOUT_TRANSITION.md instead: copy at the same root, retain old views until the PHP worker/opcode cache has refreshed and the owner dashboard works, then remove only unchanged obsolete files. Never rerun the installer or bypass recovery pins.','admin/upgrades/'],
           ['Apply database updates','Open Database updates only when the application reports pending migrations. Preserve the database and installation lock; do not reinstall to resolve pending updates.','admin/updates.php'],
           ['Review temporary data maintenance','Open Temporary data & retention and review the documented cleanup boundaries. Do not delete actual media, orders, consent, audit or recovery data as a shortcut.','admin/maintenance/'],
           ['Review administrative activity','Open Activity history to examine changes made by authorized staff. Follow up on unexpected actions before editing or restoring content.','admin/activity/'],
           ['Read the release roadmap','Open Release roadmap to review available features and planned changes. Do not assume a feature is live merely because it appears on the roadmap.','admin/roadmap.php']] as $guide){$topics['maintenance'][2][]=$guide;}
  $topics['getting-started'][2][]=['Navigate the administration dashboard','On the Overview screen review current status cards and recent activity first. Use the grouped sidebar to open Website content, Music & shows, Analytics, Bookings & communication, Store & orders, Settings & access or System & maintenance. On smaller screens open the navigation menu; choose a screen, then use Help for this screen for instructions tailored to it.','admin/'];
  $topics['pages'][2][]=['Edit a website page from start to finish','Open Pages & homepage, choose the intended page and read the field labels before changing text. Set the headline, supporting text and only the section headings you need; select an approved image already uploaded to Media library. Save private draft, inspect preview at desktop and phone sizes, publish approved content and reload the public page. An empty optional field may intentionally retain the original design.','admin/content/?kind=page'];
  $topics['members'][2][]=['Build and review a complete band profile','Open Band members and edit an existing entry or add one. Fill in the name, role and approved biography; attach an authorized portrait from Media library, check its accessible description and optional verified HTTPS website, then set Sort order. Save draft, preview desktop portrait-left/text-right and stacked phone layout, publish and verify that no duplicate member appeared.','admin/content/?kind=member'];
  $topics['media'][2][]=['Prepare an image for use on the website','Start in Media library and select the approved file. Verify crop, aspect ratio, resolution, description and rights before upload; avoid reusing tiny assets in a wide hero. After uploading, return to the page or member editor to assign the file. Uploading alone will not change a published image. Preview at the actual responsive crop before publishing.','admin/media/'];
  $topics['media'][2][]=['Maintain a photo gallery','Go to Photo gallery, create or edit the gallery record, select previously approved media and write a useful caption. Save privately and preview the visible sequence and narrow-screen presentation. Publish only when the photos, captions and display order are correct.','admin/content/?kind=gallery'];
  $topics['media'][2][]=['Add or replace a video','Open Videos, enter the approved YouTube or Vimeo destination and select an appropriate poster image if supported. Check that the URL points to the intended public video, preview its presentation and then publish. Do not upload private recordings or assume a preview publishes the item.','admin/content/?kind=video'];
  $topics['media'][2][]=['Manage downloadable press material','Upload the approved press PDF in Media library first. Open Press downloads, create or edit the record, select the uploaded asset, add a descriptive title and preview the link. Publish after confirming the public download is the correct version; retain previous material until replacement is verified.','admin/content/?kind=press'];
  $topics['music'][2][]=['Manage a music release','Open Music releases and edit or create the intended album or single. Confirm its title, approved cover artwork and any available descriptive fields. Save and preview before publishing; then check Audio tracks are linked to the right release and that the visitor-facing listing is accurate.','admin/content/?kind=release'];
  $topics['music'][2][]=['Connect an audio track to its release','Upload only audio you are authorized to publish through Media library. In Audio tracks select the release, supply the track title and required metadata, then save privately. Preview associations and ordering before publishing; double-check you did not attach a track to the wrong album.','admin/content/?kind=track'];
  $topics['music'][2][]=['Publish an accurate show announcement','In Shows & ticket links enter the performance date, timezone, venue, city and admission details. Confirm any ticket URL is the venue or authorized seller HTTPS page; preview the listing and publish. If date or venue changes later, update the existing record and verify the public announcement again.','admin/content/?kind=event'];
  $topics['analytics'][2][]=['Read the analytics dashboard','Choose the reporting interval on Audience dashboard, compare totals and trends within the same time window and check when collection began. Visitor, visit and pageview metrics describe different things. Do not infer individual identities or treat bot hits as confirmed attendees.','admin/analytics/'];
  $topics['analytics'][2][]=['Inspect visitor activity responsibly','Open Visitor explorer and use the displayed filters or date selections to narrow activity. Review timestamps and available context; distinguish repeated visits from unique visitors and account for possible automated traffic. Follow the site\'s privacy and retention policies when using the data.','admin/analytics/visitors.php'];
  $topics['analytics'][2][]=['Interpret geography reports','Open Geography data, choose the reporting window if available and review summary locations. The geographic estimate depends on available network data and can be inaccurate. It does not reveal a visitor\'s street address and should not be used for individual identification.','admin/analytics/geography.php'];
  $topics['audience'][2][]=['Process a booking inquiry','Review Booking inquiries, open the submitted request and confirm the contact details and proposed event information before responding through the approved business process. An inquiry is not an accepted show. Do not change public event listings or promise availability solely because a request was submitted.','admin/bookings/'];
  $topics['audience'][2][]=['Review newsletter consent','Open Subscribers to inspect subscription state and available consent information. Use only opted-in addresses for communication; honor unsubscribe states and avoid importing unverified lists. Coordinate delivery issues with the queue rather than repeatedly sending the same message.','admin/subscribers/'];
  $topics['audience'][2][]=['Troubleshoot the delivery queue','In Delivery queue distinguish pending, failed and completed messages. Examine available failure information, check SMTP settings and provider connectivity, then retry only where the interface supports it and duplication risk has been reviewed. Do not bypass TLS verification to make a test pass.','admin/mail/'];
  $topics['audience'][2][]=['Configure and verify email delivery','In Email settings review the sender identity, SMTP host, port, encryption and authentication fields. Use credentials from the approved mail provider without copying secrets into tickets or documentation. Save configuration and run an available test; if it fails, inspect certificate/hostname alignment and queue status before retrying.','admin/communication/'];
  $topics['commerce'][2][]=['Prepare a product for sale','In Products & inventory add or edit the merchandise record, confirm accurate description, imagery, pricing and inventory before publishing. Associate a category and review shipping and tax policies. Do not enable checkout before merchant acceptance and payment processing checks are complete.','admin/shop/'];
  $topics['commerce'][2][]=['Organize merchandise categories','Open Product categories and keep names short and distinct. Create or edit the category, then return to Products & inventory to confirm items belong to it. Check public navigation after saving; renaming a category should not unintentionally hide products.','admin/shop/categories.php'];
  $topics['commerce'][2][]=['Inspect customer records safely','Open Customers and locate the relevant record using available authorized controls. Limit access to operational needs, avoid exporting unnecessary personal information, and do not edit order payment state based solely on a customer claim.','admin/shop/customers.php'];
  $topics['commerce'][2][]=['Review an order before fulfillment','Open Orders & fulfillment, locate the correct order and inspect status and associated items. Verify successful provider-confirmed payment before shipment or delivery, then record fulfillment accurately. If a notification is missing or delayed, investigate Payment notifications rather than assuming payment succeeded.','admin/orders/'];
  $topics['commerce'][2][]=['Review store activation','Open Store settings and review whether commerce is enabled and ready. Confirm products, inventory, policy links, payment provider and notification processing first. Keep checkout inactive until the supported acceptance checks are complete.','admin/shop/settings.php'];
  $topics['commerce'][2][]=['Review shipping, tax and customer terms','Open Shipping, tax & terms and check the applicable business rules and customer-facing policies. Confirm that handling charges, geographic restrictions and published descriptions agree with actual fulfillment practices. Seek qualified tax advice where needed before enabling transactions.','admin/orders/policy.php'];
  $topics['commerce'][2][]=['Handle gateway configuration cautiously','Open Payment settings and verify the intended processor and available test/production controls. Never paste merchant credentials into the Help Center, support screenshots or source control. Complete provider-backed acceptance and webhook testing before allowing real orders.','admin/orders/payments.php'];
  $topics['commerce'][2][]=['Investigate payment notifications','Open Payment notifications and match the provider event with the associated order using identifiers displayed by the interface. Distinguish received, failed or retried notifications; prevent duplicate fulfillment. A manual status edit is not proof of payment.','admin/orders/webhooks.php'];
  $topics['account'][2][]=['Review website settings methodically','Open Website settings, review identity, site details and any configured public-facing values field by field. Record the intended change, avoid modifying unrelated configuration, save with authorized privileges and revisit the relevant public pages to confirm effects. Back up before broad or irreversible settings changes.','admin/settings.php'];
  $topics['account'][2][]=['Update search and sharing metadata','Open Search & sharing, review page titles, descriptions and available social preview assets. Keep descriptions accurate to the approved public site and use imagery suitable for sharing. Save, then verify generated page previews where possible; third-party caches may refresh later.','admin/discovery.php'];
  $topics['account'][2][]=['Give staff only necessary permissions','Open Staff access and inspect the member\'s current role before adding or changing access. Choose the least privileged role that permits the required work, save, and verify available admin navigation. Remove access promptly when it is no longer needed; do not share owner credentials.','admin/staff/'];
  $topics['account'][2][]=['Maintain your sign-in security','Open Account & security to review personal account options. Use a unique strong password and available protective sign-in options. Do not disclose recovery information or credentials through support messages; sign out from shared devices.','admin/account.php'];
  $topics['maintenance'][2][]=['Work through launch checks','Open Launch checks and inspect every warning before publication. Review HTTPS, installation state and configured settings. Resolve only verified issues, then rerun the screen\'s checks; a passing indicator does not replace physical-device visual acceptance.','admin/launch/'];
  $topics['maintenance'][2][]=['Understand installation health','Open Installation health and review any reported readiness or lock state. Preserve configuration and existing content on an installed site. Never launch a fresh installer to repair a working installation; create recovery evidence before making system changes.','admin/installation.php'];
  $topics['maintenance'][2][]=['Make a usable recovery point','Open Backups & safe restore and create the supported backup before upgrades or major edits. Verify that the archive and database state are complete and recoverable according to the interface. Record the restore point and test the recovery procedure in a safe environment; a created file alone is not proof of successful restore.','admin/backups/'];
  $topics['maintenance'][2][]=['Perform a cautious browser upgrade','Open Browser upgrades only after checking the release instructions and verifying a backup. On old folder layouts follow the documented same-root transition: preserve legacy view files until the PHP worker is refreshed and the new dashboard works. Verify sessions, admin access and content before removing checksum-confirmed obsolete files.','admin/upgrades/'];
  $topics['maintenance'][2][]=['Understand database update status','Open Database updates and inspect pending migrations. Take a verified backup first and follow the version-specific order. Do not treat a pending migration as permission to reinstall or reset the database. Verify data and administrative access afterward.','admin/updates.php'];
  $topics['maintenance'][2][]=['Handle temporary data safely','Open Temporary data & retention and read the scope of each cleanup operation. Confirm whether a target contains disposable temporary files rather than actual media, orders, subscriber consent, audit history or recovery points. Never use cleanup as a substitute for troubleshooting a broken configuration.','admin/maintenance/'];
  $topics['maintenance'][2][]=['Use activity history during an investigation','Open Activity history, inspect who made a change and when, and correlate the entry with the affected screen. Preserve relevant records before any restore or permission change. If an action is unfamiliar, review account access instead of deleting history.','admin/activity/'];
  $topics['maintenance'][2][]=['Distinguish planned and released features','Open Release roadmap to see development plans and outstanding gates. A feature listed for a release candidate is not necessarily deployed to the public website. Check the current version and release status before promising a capability to staff.','admin/roadmap.php'];
  $topics['account'][2][]=['Changing site identity safely','Open Settings & access → Website settings. Check the current values before making a change and identify which fields affect the public title, organization or contact information. Edit only the intended field, save, then inspect the public Home, Booking and footer areas as applicable. If a value is not offered by this screen, do not edit server files as a substitute; record the missing control for a future release.','admin/settings.php'];
  $topics['account'][2][]=['When a website setting does not appear to save','Confirm you used the Save control and that your session has owner privileges. Reopen Website settings to determine whether the value persisted; then inspect the public presentation separately, since caching and intentionally fixed copy can differ from saved configuration. Review Activity history if a change is missing. Do not repeatedly reinstall or overwrite configuration to force a visual refresh.','admin/settings.php'];
  $topics['account'][2][]=['Check what search engines and social sites see','Navigate to Search & sharing and review the website title, description and preview image. Save approved changes and inspect the resulting public page metadata where feasible. A shared link can show cached information until the external service refreshes it; this does not prove the admin save failed.','admin/discovery.php'];
  $topics['pages'][2][]=['Understand draft, preview and publish','A private draft is not public. In Pages & homepage choose a record, edit its fields, and Save private draft. Open its preview to review text, image crop, readability and button destination without publishing. Only Publish approved content changes visitor-facing material. Afterwards reload the public page and verify the intended record rather than assuming a draft went live.','admin/content/?kind=page'];
  $topics['pages'][2][]=['Check home page sections after an edit','Open the Home record under Pages & homepage. Review the headline, subtitle, section-heading fields, feature imagery and call-to-action controls that the editor offers. Leave intentionally designed fallback text blank if it should remain unchanged. Preview the top hero and lower sections at wide and narrow widths before publishing.','admin/content/?kind=page'];
  $topics['members'][2][]=['Fix a missing profile or wrong member order','Open Band members to confirm whether the member is saved, published or intentionally removed. Check Sort order: lower values appear first. If the profile exists as a private draft, preview it and publish only when approved. Confirm the portrait file is available in Media library. Do not re-import the legacy roster as a fix for an intentionally deleted member.','admin/content/?kind=member'];
  $topics['media'][2][]=['Choose an image that will not stretch','Check the aspect ratio and source dimensions before assigning an uploaded image. A wide hero needs wide source artwork and a suitable crop; increasing CSS display dimensions cannot restore detail missing from a small image. Preview the final page at desktop and mobile widths and confirm important artwork is not cropped by the responsive container. Keep the original approved file available for comparison.','admin/media/'];
  $topics['maintenance'][2][]=['Before changing a large number of pages','Back up the installed files, database and private state before broad changes. Verify that the backup is recoverable and note the previous published content. Edit one page or member first, preview and publish it, and verify the result before repeating across many entries. Avoid mixing a major content update with an application upgrade in the same unverified operation.','admin/backups/'];
  $topics['media'][2][]=['Upload images directly while editing','Open Pages & homepage or Band members, select the image field, and choose Or upload a new image directly. Add a descriptive image alternative, confirm publishing rights, then Save private draft or Publish approved content. The image is stored in the private media system automatically. Phone JPEG orientation is corrected on upload when the PHP EXIF extension is available. Larger images are supported up to the application 50 MB cap, but your PHP upload_max_filesize and post_max_size may still need hosting configuration.','admin/media/'];
  $topics['pages'][2][]=['Use the included Band hero artwork','The Band-page hero bundled with this release shows Chad playing guitar, Charlie playing drums and Ron playing harmonica with the crowned gorilla. The Press page keeps its previous hero; this change applies only to Band. Its default background uses the previous WebP artwork, a PNG fallback and the existing dark base color. Open Pages & homepage and select Band. If that page has a published Feature image, it overrides the bundled hero: clear the image selection only if you want to use the included design, then save privately, preview desktop and mobile, and publish when approved. Do not delete a shared Media library image to change the fallback.','admin/content/?kind=page'];
  $topics['pages'][2][]=['Band hero looks duplicated or too short','The updated Band fallback uses one tall stage image on desktop: Chad on guitar, Charlie on drums and Ron on harmonica. A previous desktop layout drew the same band photograph twice, producing duplicate-looking members; the duplicate foreground image is now hidden. The normal compact image remains on phones. If changes do not appear on the website, check that the updated site package is installed; Admin content changes alone do not install replacement website assets.','admin/content/?kind=page'];
  $topics['maintenance'][2][]=['Review a separate staging Admin safely','Use GitHub Actions only with a staging website on a separate database, not the live website. Add repository secrets SPIRIT_STAGING_BASE_URL, SPIRIT_STAGING_ADMIN_EMAIL and SPIRIT_STAGING_ADMIN_PASSWORD, then explicitly apply the staging-admin-review label to draft PR 39 to request the read-only browser review. It visits permitted Admin screens and preserves redacted Help screenshots, but does not publish, change settings or test live payments. Check the result before approving release.','admin/roadmap.php'];
  $topics['maintenance'][2][]=['Check Admin screens before a release','The automated candidate Website and installer checks open every permitted owner administration destination on disposable root and subfolder installations. They check pages, contextual Help and direct image-upload editors using GET only. These synthetic tests do not prove a live site has been updated or that its real Admin login works. Record the exact failing path when investigating a production problem; never share passwords in a report.','admin/launch/'];
  return $topics;
 }
}
